 "path": "programs/task-2b862c63.py",
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                out[r][c] = grid[r][w - 1 - c]
    return out
